SELECT AVG(t.win::int) AS win_rate
FROM teams t
WHERE t.team_id = 100;

SELECT COUNT(*) AS partidas_vencidas
FROM teams
WHERE team_id = 200 AND win = true;

SELECT AVG(gold_earned) AS media_ouro_jungle
FROM participants
WHERE team_position = 'JUNGLE';

SELECT AVG(barons) AS media_baraes_time_vencedor
FROM teams
WHERE win = true;

SELECT COUNT(*) AS partidas
FROM matches
WHERE game_duration_s > 1800;

SELECT AVG(dmg_to_champions) AS media_dano_time_azul
FROM participants
WHERE team_id = 100;

SELECT COUNT(DISTINCT puuid) AS jogadores_challenger
FROM players
WHERE UPPER(tier) = 'CHALLENGER';

SELECT AVG(cs_total) AS cs_medio_top
FROM participants
WHERE team_position = 'TOP';

SELECT COUNT(DISTINCT t.match_id) AS partidas
FROM teams t
WHERE t.heralds >= 1 AND t.win = true;

SELECT COUNT(DISTINCT game_id) AS jogos
FROM pro_games
WHERE year = 2026;

SELECT AVG(CASE WHEN side = 'Blue' THEN win::int ELSE NULL END) AS win_rate_azul
FROM pro_games
WHERE year = 2026 AND side = 'Blue';
